INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('100', '16', '2', '2', 'proof', '14', '证明当 \(0<x<\pi/2\) 时，
\[\frac4{\pi^2}<\frac1{x^2}-\frac1{2\tan^2x}<\frac23.\]', '所给双边不等式成立。', '令 \(F(x)=x^{-2}-(2\tan^2x)^{-1}\)。通过求导并用均值不等式证明 \(F\) 严格递减；再计算 \(x\to0^+\) 与 \(x\to(\pi/2)^-\) 的端点极限分别为 \(2/3\)、\(4/\pi^2\)。', '2017 年第八届全国大学生数学竞赛决赛（非数学类） 证明当 (0<x< /2 ) 时， [ 4 2 < 1 x 2 - 1 2 2x < 23. ] 所给双边不等式成立。 令 (F(x)=x -2 -(2 2x) -1 )。通过求导并用均值不等式证明 (F ) 严格递减；再计算 (x 0 + ) 与 (x ( /2) - ) 的端点极限分别为 (2/3 )、 (4/ 2 )。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('105', '17', '1', '1', 'calculation', '42', '填空题，共 6 小题，每小题 7 分。

1. 可导函数满足 \(f(x)\cos x+2\int_0^xf(t)\sin t\,dt=x+1\)，求 \(f(x)\)。
2. 求 \(\displaystyle\lim_{n\to\infty}\sin^2(\pi\sqrt{n^2+n})\)。
3. \(w=f(u,v)\)，\(u=x-cy,v=x+cy\)，求 \(w_{xx}-c^{-2}w_{yy}\)。
4. \(f(0)=f''(0)=0,f''''(0)=6\)，求 \(\displaystyle\lim_{x\to0}f(\sin^2x)/x^4\)。
5. 求 \(\displaystyle\int\frac{e^{-\sin x}\sin2x}{(1-\sin x)^2}\,dx\)。
6. 两曲面 \(z^2=x^2+y^2\)、\(z^2=4-x^2-y^2\) 围成区域 \(V\)，求 \(\iiint_Vz^2\,dV\)。', '1. \(f=\sin x+\cos x\)。 2. \(1\)。 3. \(4f_{uv}\)。 4. \(3\)。
5. \(\displaystyle\frac{2e^{-\sin x}}{1-\sin x}+C\)。 6. \(2\pi\)。', '1. 令 \(x=0\) 得初值，求导后解一阶线性方程。2. 减去 \(n\pi\) 后用基本极限。
3. 连续两次链式求导。4. 用 \(f(t)=3t^2+o(t^2)\)。5. 令 \(t=\sin x\) 直接积分。
6. 以 \(z=\sqrt2\) 分上下两部分，截面圆面积积分均为 \(\pi\)。', '2017 年第九届全国大学生数学竞赛初赛（非数学类） 填空题，共 6 小题，每小题 7 分。 1. 可导函数满足 (f(x) x+2 0 xf(t) t ,dt=x+1 )，求 (f(x) )。 2. 求 ( n 2( n 2+n ) )。 3. (w=f(u,v) )， (u=x-cy,v=x+cy )，求 (w xx -c -2 w yy )。 4. (f(0)=f''(0)=0,f''''(0)=6 )，求 ( x 0 f( 2x)/x 4 )。 5. 求 ( e - x 2x (1- x) 2 ,dx )。 6. 两曲面 (z 2=x 2+y 2 )、 (z 2=4-x 2-y 2 ) 围成区域 (V )，求 ( Vz 2 ,dV )。 1. (f= x+ x )。 2. (1 )。 3. (4f uv )。 4. (3 )。 5. ( 2e - x 1- x +C )。 6. (2 )。 1. 令 (x=0 ) 得初值，求导后解一阶线性方程。2. 减去 (n ) 后用基本极限。 3. 连续两次链式求导。4. 用 (f(t)=3t 2+o(t 2) )。5. 令 (t= x ) 直接积分。 6. 以 (z= 2 ) 分上下两部分，截面圆面积积分均为 ( )。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('106', '17', '2', '2', 'proof', '14', '设 \(f(x,y)\) 有连续二阶偏导。对任意 \(\alpha\)，令 \(g_\alpha(t)=f(t\cos\alpha,t\sin\alpha)\)。若 \(g_\alpha''(0)=0\)、\(g_\alpha''''(0)>0\)，证明 \(f(0,0)\) 是极小值。', '\(f(0,0)\) 是严格极小值。', '第一条件对所有方向成立，故 \(\nabla f(0,0)=0\)。第二条件说明 Hessian 二次型对每个非零方向均为正，因而 Hessian 正定。二元函数极值充分条件即给出结论。', '2017 年第九届全国大学生数学竞赛初赛（非数学类） 设 (f(x,y) ) 有连续二阶偏导。对任意 ( )，令 (g (t)=f(t ,t ) )。若 (g ''(0)=0 )、 (g ''''(0)>0 )，证明 (f(0,0) ) 是极小值。 (f(0,0) ) 是严格极小值。 第一条件对所有方向成立，故 ( f(0,0)=0 )。第二条件说明 Hessian 二次型对每个非零方向均为正，因而 Hessian 正定。二元函数极值充分条件即给出结论。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('107', '17', '3', '3', 'calculation', '14', '曲线 \(\Gamma\) 为 \(x^2+y^2+z^2=1,x+z=1\) 在第一卦限从 \(A(1,0,0)\) 到 \(B(0,0,1)\) 的一段。求
\[I=\int_\Gamma y\,dx+z\,dy+x\,dz.\]', '\(I=\dfrac12-\dfrac\pi2\)。', '参数化为 \(x=(1+\cos t)/2,y=(\sqrt2/2)\sin t,z=(1-\cos t)/2\)，\(0\le t\le\pi\)。代入并积分，得 \(I=1/2-\pi/2\)。', '2017 年第九届全国大学生数学竞赛初赛（非数学类） 曲线 ( ) 为 (x 2+y 2+z 2=1,x+z=1 ) 在第一卦限从 (A(1,0,0) ) 到 (B(0,0,1) ) 的一段。求 [I= y ,dx+z ,dy+x ,dz. ] (I= 12- 2 )。 参数化为 (x=(1+ t)/2,y=( 2/2) t,z=(1- t)/2 )， (0 t )。代入并积分，得 (I=1/2- /2 )。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('108', '17', '4', '4', 'proof', '15', '设连续函数 \(f(x)>0\)，且对任意实数 \(t\)，\(\int_{-\infty}^{\infty}e^{-|t-x|}f(x)\,dx\le1\)。证明对 \(a<b\)，
\[\int_a^bf(x)\,dx\le\frac{b-a+2}{2}.\]', '所给估计成立。', '把条件先限制到 \([a,b]\)，再对 \(t\in[a,b]\) 积分并交换积分次序。内积分为 \(2-e^{a-x}-e^{x-b}\)。整理后，余下两个指数加权积分均由题设不超过 1，即得结论。', '2017 年第九届全国大学生数学竞赛初赛（非数学类） 设连续函数 (f(x)>0 )，且对任意实数 (t )， ( - e -|t-x| f(x) ,dx 1 )。证明对 (a<b )， [ a bf(x) ,dx b-a+2 2 . ] 所给估计成立。 把条件先限制到 ([a,b] )，再对 (t [a,b] ) 积分并交换积分次序。内积分为 (2-e a-x -e x-b )。整理后，余下两个指数加权积分均由题设不超过 1，即得结论。', '1', 'published') ON CONFLICT (id) DO NOTHING;